<h1>مدیریت تجربه‌ها</h1><nav class="row section"><a class="primary" href="<?= $this->h($this->url('/experience/edit')) ?>">ثبت تجربه جدید</a><a class="secondary" href="<?= $this->h($this->url('/experiences?status=submitted')) ?>">در انتظار بررسی</a><a class="secondary" href="<?= $this->h($this->url('/taxonomy')) ?>">موضوعات و مسائل</a><a class="secondary" href="<?= $this->h($this->url('/storefront')) ?>">چیدمان صفحه اصلی</a></nav>
<form method="get" class="card section"><input type="hidden" name="r" value="/experiences"><div class="grid2"><?= $this->field('q','عنوان، مسئله یا نام مرشد','search',is_string($_GET['q']??null)?$_GET['q']:'',false) ?><label>وضعیت<select name="status"><option value="">همه</option><?php foreach(['draft','submitted','changes','approved','rejected'] as $k): ?><option value="<?= $k ?>" <?= ($_GET['status']??'')===$k?'selected':'' ?>><?= $this->status($k) ?></option><?php endforeach; ?></select></label><label>صاحب تجربه<select name="mentor_id"><option value="">همه</option><?php foreach($mentors as $m): ?><option value="<?= $this->h($m['user_id']) ?>" <?= ($_GET['mentor_id']??'')===$m['user_id']?'selected':'' ?>><?= $this->h($m['display_name']) ?></option><?php endforeach; ?></select></label><label>حوزه یا مسئله<select name="term_id"><option value="">همه</option><?php foreach($terms as $t): ?><option value="<?= $this->h($t['id']) ?>" <?= ($_GET['term_id']??'')===$t['id']?'selected':'' ?>><?= $this->h($t['title']) ?></option><?php endforeach; ?></select></label><label>از تاریخ<input type="date" name="from" value="<?= $this->h($_GET['from']??'') ?>"></label><label>تا تاریخ<input type="date" name="to" value="<?= $this->h($_GET['to']??'') ?>"></label></div><button>اعمال فیلتر</button></form>
<div class="row section"><?php foreach($stats as $stat): ?><span class="tag"><?= $this->status($stat['status']) ?>: <?= (int)$stat['total'] ?></span><?php endforeach; ?></div>
<div class="experience-admin-list"><?php foreach($rows as $r): ?><article class="card section"><h2><?= $this->h($r['title']) ?></h2><p><?= $this->h($r['display_name']) ?> · نسخه <?= (int)$r['version_no'] ?> · <?= $this->status($r['status']) ?></p><p>نسخه عمومی: <?= $r['public_version_id']?'منتشرشده':'منتشر نشده' ?> · کیفیت: <?= $this->h(['incomplete'=>'ناقص','ready'=>'قابل ثبت','rich'=>'غنی'][$r['quality_level']??'']??'ساختار قدیمی') ?></p><p class="small muted">روش ثبت: دستی · <time data-timestamp="<?= (int)$r['created_at'] ?>"><?= gmdate('Y-m-d',$r['created_at']) ?></time></p><div class="store-actions"><a class="secondary" href="<?= $this->h($this->url('/experience/edit?id='.$r['experience_id'])) ?>">ویرایش / تکمیل</a><a class="secondary" href="<?= $this->h($this->url('/experience?id='.$r['id'])) ?>">پیش‌نمایش و بررسی</a></div></article><?php endforeach; ?></div><?php if(!$rows): ?><p class="card section">تجربه‌ای با این فیلتر پیدا نشد.</p><?php endif; ?>
